/* Geometry-only emergency tracking draft. No RF receiver or cryptographic verifier.
 * identityVerified is supplied by the transport boundary, never by packet fields.
 * The browser demonstration is the only implemented transport. */
import {distanceM,pointAlong,pathLength,bearingDeg} from './geometry.js';
import {beaconAuthorization} from './fleet.js';
const RAD=Math.PI/180,R=6371008.8;
const xy=(p,o)=>[(p[1]-o[1])*RAD*R*Math.cos(o[0]*RAD),(p[0]-o[0])*RAD*R];
const ll=(v,o)=>[o[0]+v[1]/R/RAD,o[1]+v[0]/(R*Math.cos(o[0]*RAD))/RAD];
export const headingDifference=(a,b)=>Math.abs(((a-b+540)%360)-180);
export function projectToLane(point,lane){let along=0,best=null;for(let i=1;i<lane.path.length;i++){const a=lane.path[i-1],b=lane.path[i],v=xy(b,a),w=xy(point,a),length=Math.hypot(...v);if(!length)continue;const raw=(w[0]*v[0]+w[1]*v[1])/(length*length),u=Math.max(0,Math.min(1,raw)),q=ll([v[0]*u,v[1]*u],a),distance=distanceM(point,q);if(!best||distance<best.distance_m){best={distance_m:distance,chainage_m:along+length*(i===1&&raw<0?raw:u),incoming_heading_deg:(bearingDeg([a,b])+180)%360};}along+=length;}return best;}
export function matchIncomingLane(project,position,heading,accuracy){const candidates=[];for(const site of project.intersections)for(const lane of site.lanes.filter(l=>l.flow==='inbound')){const hit=projectToLane(position,lane);if(!hit||hit.chainage_m<=0||hit.chainage_m>150||hit.distance_m>18)continue;const difference=headingDifference(heading,hit.incoming_heading_deg);if(difference>35)continue;candidates.push({site,lane,...hit,heading_error_deg:difference,score:hit.distance_m+difference/10});}candidates.sort((a,b)=>a.score-b.score);const best=candidates[0];if(!best)return null;const otherApproach=candidates.find(x=>x.site.id!==best.site.id||x.lane.arm_id!==best.lane.arm_id),nextLane=candidates.find(x=>x.site.id===best.site.id&&x.lane.id!==best.lane.id);const laneCertain=best.distance_m+accuracy<(best.lane.lane_width_m||3)/2&&(!nextLane||nextLane.distance_m-best.distance_m>2*accuracy);return {intersection_id:best.site.id,controller_id:best.site.controller_device_id,approach:best.lane.approach,road_name:best.lane.road_name,axis:['N','S'].includes(best.lane.approach)?'NS':'EW',candidate_lane_id:best.lane.id,lane_id:laneCertain?best.lane.id:null,lane_confidence:laneCertain?'geometric candidate':'ambiguous',approach_confident:accuracy<=12&&(!otherApproach||otherApproach.score-best.score>Math.max(3,accuracy)),distance_to_reference_m:best.chainage_m,cross_track_m:best.distance_m,heading_error_deg:best.heading_error_deg,geometry_verified:false};}
export function demoPosition(lane,chainage){if(chainage>=0)return pointAlong(lane.path,Math.min(chainage,pathLength(lane.path)));const [a,b]=lane.path,v=xy(b,a),length=Math.hypot(...v);return ll([v[0]/length*chainage,v[1]/length*chainage],a);}
export class BeaconTracker{
 constructor(project,{freshness_s=3,max_speed_mps=55,max_priority_s=20}={}){this.project=project;this.freshness_s=freshness_s;this.max_speed_mps=max_speed_mps;this.max_priority_s=max_priority_s;this.tracks=new Map();}
 receive(packet,now,{identityVerified=false}={}){
  if(!packet||packet.schema!=='pasada.beacon/0.1.0')return {accepted:false,reason:'unsupported packet'};
  const device=this.project.devices.find(d=>d.id===packet.beacon_id&&d.role==='beacon');if(!identityVerified||!device)return {accepted:false,reason:'identity not verified / enrolled'};
  if(this.project.vehicles!==undefined&&(typeof packet.vehicle_id!=='string'||!beaconAuthorization(this.project,packet.beacon_id,packet.vehicle_id).allowed))return {accepted:false,reason:'vehicle / beacon authorization rejected'};
  if(typeof packet.boot_id!=='string'||!packet.boot_id||packet.boot_id.length>64||!Number.isSafeInteger(packet.sequence)||packet.sequence<1||!Number.isFinite(packet.timestamp_s)||!Number.isFinite(packet.latitude)||Math.abs(packet.latitude)>90||!Number.isFinite(packet.longitude)||Math.abs(packet.longitude)>180||!Number.isFinite(packet.position_accuracy_m)||packet.position_accuracy_m<=0||packet.position_accuracy_m>100||typeof packet.emergency_active!=='boolean')return {accepted:false,reason:'invalid fix'};
  if(now-packet.timestamp_s>this.freshness_s||packet.timestamp_s>now+.5)return {accepted:false,reason:'stale / future packet'};
  const old=this.tracks.get(packet.beacon_id);if(old&&(old.boot_id!==packet.boot_id||packet.sequence<=old.sequence||packet.timestamp_s<=old.timestamp_s))return {accepted:false,reason:'duplicate, out-of-order or unverified session change'};
  const pos=[packet.latitude,packet.longitude];let heading=null,speed=null,motionWindow=null,anchor=old?.motion_anchor||{position:pos,t:packet.timestamp_s,accuracy:packet.position_accuracy_m};
  const elapsed=packet.timestamp_s-anchor.t,moved=distanceM(anchor.position,pos),minimumMotion=Math.max(2,2*Math.hypot(anchor.accuracy,packet.position_accuracy_m));
  if(elapsed>0&&moved/elapsed>this.max_speed_mps)return {accepted:false,reason:'implausible position jump'};
  if(old){const dt=packet.timestamp_s-old.timestamp_s;if(dt>0&&distanceM([old.latitude,old.longitude],pos)/dt>this.max_speed_mps)return {accepted:false,reason:'implausible position jump'};}
  if(elapsed>0&&elapsed<=10&&moved+.001>=minimumMotion){heading=bearingDeg([anchor.position,pos]);speed=moved/elapsed;motionWindow=elapsed;anchor={position:pos,t:packet.timestamp_s,accuracy:packet.position_accuracy_m};}
  else if(elapsed>10)anchor={position:pos,t:packet.timestamp_s,accuracy:packet.position_accuracy_m};
  const retainedHeading=heading===null&&old?.heading_deg!==null&&Number.isFinite(old?.heading_deg)&&old?.first_eligible_s!==null;if(retainedHeading)heading=old.heading_deg;
  const previousMatch=old?.match;let passed=old?.passed||false;if(previousMatch){const site=this.project.intersections.find(j=>j.id===previousMatch.intersection_id),lane=site?.lanes.find(l=>l.id===previousMatch.candidate_lane_id);if(lane&&projectToLane(pos,lane)?.chainage_m<=0)passed=true;}
  const match=heading!==null&&!passed?matchIncomingLane(this.project,pos,heading,packet.position_accuracy_m):null;
  const eligible=packet.emergency_active&&!passed&&(speed!==null&&speed>=.5||retainedHeading)&&match?.approach_confident;
  const firstEligible=old?.first_eligible_s??(eligible?now:null),leaseEnd=firstEligible===null?null:firstEligible+this.max_priority_s;
  const track={...packet,identity_status:'verified by simulation boundary',received_at_s:now,heading_deg:heading,heading_source:retainedHeading?'retained approach heading':'position delta',speed_mps:speed,motion_window_s:motionWindow,motion_anchor:anchor,match,passed,first_eligible_s:firstEligible,lease_end_s:leaseEnd,priority_eligible:!!eligible&&now<leaseEnd,status:passed?'passed reference':!packet.emergency_active?'emergency inactive':leaseEnd!==null&&now>=leaseEnd?'priority window elapsed':heading===null?'waiting for reliable movement':!match?'no incoming approach match':!match.approach_confident?'ambiguous approach':leaseEnd!==null&&now>=leaseEnd?'priority window elapsed':retainedHeading?'on tracked approach':speed!==null&&speed<.5?'insufficient approach motion':'approaching'};
  this.tracks.set(packet.beacon_id,track);return {accepted:true,track:this.view(track,now)};
 }
 view(track,now){const {motion_anchor,...out}=track,age=Math.max(0,now-track.received_at_s),allowed=beaconAuthorization(this.project,track.beacon_id,track.vehicle_id).allowed;return {...out,age_s:age,priority_eligible:track.priority_eligible&&age<this.freshness_s&&allowed,status:!allowed?'authorization inactive':age>=this.freshness_s?'stale':track.status,eta_s:age<this.freshness_s&&track.match&&track.speed_mps>0?track.match.distance_to_reference_m/track.speed_mps:null};}
 snapshot(now){return [...this.tracks.values()].map(t=>this.view(t,now));}
}
